         "details": "Create a filename parsing system that analyzes selected image names to identify known tags and consistent patterns. The implementation should include:

1. A utility function to parse filenames and split them by common separators (like '_', '-', ' '):
```python
def parse_filename(filename):
    # Strip extension
    name_without_ext = os.path.splitext(filename)[0]
    # Split by common separators
    parts = re.split(r'[_\-\s]', name_without_ext)
    return [part for part in parts if part]
```

2. A function to identify which parts of the filename match known tags:
```python
def identify_tags_in_filename(parts, tag_manager):
    known_tags = []
    unknown_parts = []
    all_tags = tag_manager.get_all_tags()

    for part in parts:
        if part.lower() in [tag.lower() for tag in all_tags]:
            known_tags.append(part)
        else:
            unknown_parts.append(part)

    return known_tags, unknown_parts
```

3. Logic to determine common patterns across multiple selected files:
```python
def find_common_patterns(filenames, tag_manager):
    if not filenames:
        return [], []

    # Parse each filename
    parsed_files = []
    for filename in filenames:
        parts = parse_filename(filename)
        known_tags, unknown_parts = identify_tags_in_filename(parts, tag_manager)
        parsed_files.append({
            'filename': filename,
            'known_tags': known_tags,
            'unknown_parts': unknown_parts
        })

    # Find common tags across all files
    common_tags = set(parsed_files[0]['known_tags'])
    for file_data in parsed_files[1:]:
        common_tags.intersection_update(file_data['known_tags'])

    # Find common prefix/suffix patterns
    common_prefix = []
    if all(len(f['unknown_parts']) > 0 for f in parsed_files):
        # Check if first parts match
        first_parts = [f['unknown_parts'][0] for f in parsed_files]
        if all(p == first_parts[0] for p in first_parts):
            common_prefix.append(first_parts[0])

    return list(common_tags), common_prefix
```

4. API endpoint to provide pattern information:
```python
@app.route('/api/analyze_filenames', methods=['POST'])
def analyze_filenames():
    data = request.json
    selected_files = data.get('filenames', [])

    if not selected_files:
        return jsonify({'error': 'No files selected'}), 400

    common_tags, common_prefix = find_common_patterns(selected_files, tag_manager)

    return jsonify({
        'common_tags': common_tags,
        'common_prefix': common_prefix
    })
```

5. Frontend JavaScript to request and display the detected patterns:
```javascript
function analyzeSelectedFilenames() {
    const selectedFiles = getSelectedFiles();

    if (selectedFiles.length === 0) return;

    fetch('/api/analyze_filenames', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ filenames: selectedFiles })
    })
    .then(response => response.json())
    .then(data => {
        // Pre-select detected tags
        if (data.common_tags && data.common_tags.length > 0) {
            preSelectTags(data.common_tags);
        }

        // Pre-fill prefix field
        if (data.common_prefix && data.common_prefix.length > 0) {
            document.getElementById('prefix-field').value = data.common_prefix.join('_');
        }
    })
    .catch(error => console.error('Error analyzing filenames:', error));
}

// Call this when files are selected
document.getElementById('file-selection').addEventListener('change', analyzeSelectedFilenames);
```

